1	package simulator
2	
3	import (
4		"context"
5		"encoding/binary"
6		"fmt"
7		"os/exec"
8		"strings"
9		"sync"
10		"time"
11	
12		"knirvhasher/pkg/hashing/core"
13		"knirvhasher/pkg/hashing/methods/cuda"
14		"knirvhasher/pkg/hashing/methods/software"
15	)
16	
17	// HasherWrapper implements the HashSimulator interface using hasher's HashMethod
18	// This replaces the internal vhasher simulator with the production-grade hasher module
19	type HasherWrapper struct {
20		hashMethod core.HashMethod
21		config     *SimulatorConfig
22		cache      map[string]uint32
23		cacheMutex sync.RWMutex
24		isRunning  bool
25		mutex      sync.RWMutex
26		methodType string // "auto", "software", "cuda"
27	}
28	
29	// NewHasherWrapper creates a new HashSimulator wrapper using hasher's HashMethod
30	// It defaults to software implementation if no hardware is available
31	func NewHasherWrapper(config *SimulatorConfig) *HasherWrapper {
32		if config == nil {
33			config = &SimulatorConfig{
34				DeviceType:     "software",
35				MaxConcurrency: 100,
36				TargetHashRate: 500000000,
37				CacheSize:      10000,
38				GPUDevice:      0,
39				Timeout:        30,
40			}
41		}
42	
43		return &HasherWrapper{
44			config:    config,
45			cache:     make(map[string]uint32),
46			isRunning: false,
47		}
48	}
49	
50	// Initialize sets up the HashMethod based on configuration
51	func (h *HasherWrapper) Initialize(config *SimulatorConfig) error {
52		h.mutex.Lock()
53		defer h.mutex.Unlock()
54	
55		if config != nil {
56			h.config = config
57			// Check if method type is specified in DeviceType
58			if strings.Contains(config.DeviceType, "software") {
59				h.methodType = "software"
60			} else if strings.Contains(config.DeviceType, "cuda") {
61				h.methodType = "cuda"
62			} else {
63				h.methodType = "auto"
64			}
65		}
66	
67		// Initialize hash method based on type
68		if h.hashMethod == nil {
69			var err error
70			h.hashMethod, err = h.createHashMethod()
71			if err != nil {
72				return fmt.Errorf("failed to create hash method: %w", err)
73			}
74	
75			if err := h.hashMethod.Initialize(); err != nil {
76				return fmt.Errorf("failed to initialize hash method: %w", err)
77			}
78			fmt.Printf("[SIM] Using hash method: %s\n", h.hashMethod.Name())
79		}
80	
81		h.isRunning = true
82		return nil
83	}
84	
85	// createHashMethod creates the appropriate hash method based on configuration
86	func (h *HasherWrapper) createHashMethod() (core.HashMethod, error) {
87		switch h.methodType {
88		case "cuda":
89			// Directly create CUDA method
90			cudaMethod := cuda.NewCudaMethod()
91			if cudaMethod.IsAvailable() {
92				return cudaMethod, nil
93			}
94			// Fall back to software if CUDA not available
95			return software.NewSoftwareMethod(), nil
96	
97		case "software":
98			return software.NewSoftwareMethod(), nil
99	
100		case "auto":
101			// Auto-detect: try CUDA first, then software
102			if h.isCUDAAvailable() {
103				cudaMethod := cuda.NewCudaMethod()
104				if cudaMethod.IsAvailable() {
105					return cudaMethod, nil
106				}
107			}
108			return software.NewSoftwareMethod(), nil
109	
110		default:
111			return software.NewSoftwareMethod(), nil
112		}
113	}
114	
115	// isCUDAAvailable checks if CUDA is available on the system with a 5-second timeout.
116	// nvidia-smi can hang indefinitely on systems with flaky GPU drivers, so a timeout
117	// prevents the data-trainer from blocking at startup.
118	func (h *HasherWrapper) isCUDAAvailable() bool {
119		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
120		defer cancel()
121		cmd := exec.CommandContext(ctx, "nvidia-smi")
122		err := cmd.Run()
123		if err != nil {
124			return false
125		}
126		return ctx.Err() == nil
127	}
128	
129	// SetHashMethod allows injection of a specific HashMethod (e.g., ASIC, CUDA)
130	func (h *HasherWrapper) SetHashMethod(method core.HashMethod) {
131		h.mutex.Lock()
132		defer h.mutex.Unlock()
133		h.hashMethod = method
134	}
135	
136	// SetMethodType sets the hash method type (auto, software, cuda)
137	func (h *HasherWrapper) SetMethodType(methodType string) {
138		h.mutex.Lock()
139		defer h.mutex.Unlock()
140		h.methodType = methodType
141	}
142	
143	// Shutdown cleans up the HashMethod
144	func (h *HasherWrapper) Shutdown() error {
145		h.mutex.Lock()
146		defer h.mutex.Unlock()
147	
148		h.isRunning = false
149	
150		if h.hashMethod != nil {
151			if err := h.hashMethod.Shutdown(); err != nil {
152				return fmt.Errorf("failed to shutdown hash method: %w", err)
153			}
154		}
155	
156		h.cacheMutex.Lock()
157		h.cache = make(map[string]uint32)
158		h.cacheMutex.Unlock()
159	
160		return nil
161	}
162	
163	// SimulateHash performs deterministic hashing using the HashMethod
164	// Maps to: SHA256(seed || pass) with caching
165	func (h *HasherWrapper) SimulateHash(seed []byte, pass int) (uint32, error) {
166		if !h.isRunning {
167			return 0, fmt.Errorf("simulator is not running")
168		}
169	
170		if h.hashMethod == nil {
171			return 0, fmt.Errorf("hash method not initialized")
172		}
173	
174		// Create cache key
175		cacheKey := fmt.Sprintf("%x_%d", seed, pass)
176	
177		// Check cache
178		h.cacheMutex.RLock()
179		if cached, exists := h.cache[cacheKey]; exists {
180			h.cacheMutex.RUnlock()
181			return cached, nil
182		}
183		h.cacheMutex.RUnlock()
184	
185		// Combine seed with pass for deterministic hashing
186		data := make([]byte, len(seed)+4)
187		copy(data, seed)
188		binary.LittleEndian.PutUint32(data[len(seed):], uint32(pass))
189	
190		// Use HashMethod for computation
191		hash, err := h.hashMethod.ComputeHash(data)
192		if err != nil {
193			return 0, fmt.Errorf("hash computation failed: %w", err)
194		}
195	
196		// Extract first 4 bytes as uint32 result (Big-Endian for simulator compatibility)
197		result := binary.BigEndian.Uint32(hash[:4])
198	
199		// Cache result
200		if len(h.cache) < h.config.CacheSize {
201			h.cacheMutex.Lock()
202			h.cache[cacheKey] = result
203			h.cacheMutex.Unlock()
204		}
205	
206		return result, nil
207	}
208	
209	// SimulateBitcoinHeader returns first 4 bytes of Double-SHA256 as uint32
210	func (h *HasherWrapper) SimulateBitcoinHeader(header []byte) (uint32, error) {
211		if !h.isRunning {
212			return 0, fmt.Errorf("simulator is not running")
213		}
214	
215		if h.hashMethod == nil {
216			return 0, fmt.Errorf("hash method not initialized")
217		}
218	
219		// Use MineHeader with a 0-0 range to just get the hash of the current header
220		// or better, if the hashMethod supports a direct double-hash.
221		// Most HashMethods implement double-hash internally for MineHeader.
222		// But core.HashMethod doesn't have a direct "ComputeDoubleHash" exposed.
223		// It has ComputeHash.
224	
225		hash1, err := h.hashMethod.ComputeHash(header)
226		if err != nil {
227			return 0, err
228		}
229	
230		hash2, err := h.hashMethod.ComputeHash(hash1[:])
231		if err != nil {
232			return 0, err
233		}
234	
235		return binary.BigEndian.Uint32(hash2[:4]), nil
236	}
237	
238	// RecursiveMine performs the 21-pass temporal loop with associative jitter
239	// Returns the full 32-byte double-SHA256 hash of the final pass
240	func (h *HasherWrapper) RecursiveMine(header []byte, passes int) ([]byte, error) {
241		if !h.isRunning {
242			return nil, fmt.Errorf("simulator is not running")
243		}
244	
245		if h.hashMethod == nil {
246			return nil, fmt.Errorf("hash method not initialized")
247		}
248	
249		// Delegate directly to the production-grade recursive mine implementation
250		return h.hashMethod.ExecuteRecursiveMine(header, passes)
251	}
252	
253	// ValidateSeed checks if seed produces target token in any pass
254	func (h *HasherWrapper) ValidateSeed(seed []byte, targetToken int32) (bool, error) {
255		if !h.isRunning {
256			return false, fmt.Errorf("simulator is not running")
257		}
258	
259		// Check multiple passes
260		for pass := 0; pass < 21; pass++ {
261			nonce, err := h.SimulateHash(seed, pass)
262			if err != nil {
263				return false, err
264			}
265	
266			if nonce == uint32(targetToken) {
267				return true, nil
268			}
269		}
270	
271		return false, nil
272	}
273	
274	// ProcessHeadersBatch processes multiple Bitcoin headers in parallel
275	func (h *HasherWrapper) ProcessHeadersBatch(headers [][]byte, targetTokenID uint32) ([]uint32, error) {
276		if !h.isRunning {
277			return nil, fmt.Errorf("simulator is not running")
278		}
279	
280		results := make([]uint32, len(headers))
281		for i, header := range headers {
282			result, err := h.SimulateBitcoinHeader(header)
283			if err != nil {
284				continue
285			}
286			results[i] = result
287		}
288	
289		return results, nil
290	}
291	
292	// GetHashMethod returns the underlying HashMethod for advanced usage
293	func (h *HasherWrapper) GetHashMethod() core.HashMethod {
294		h.mutex.RLock()
295		defer h.mutex.RUnlock()
296		return h.hashMethod
297	}
298	
299	// ClearCache clears the internal cache
300	func (h *HasherWrapper) ClearCache() {
301		h.cacheMutex.Lock()
302		defer h.cacheMutex.Unlock()
303		h.cache = make(map[string]uint32)
304	}
305	
306	// GetCacheSize returns current cache size
307	func (h *HasherWrapper) GetCacheSize() int {
308		h.cacheMutex.RLock()
309		defer h.cacheMutex.RUnlock()
310		return len(h.cache)
311	}
