1	package transformer
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"io"
9		"net/http"
10		"time"
11	)
12	
13	// ExternalGenerateFn is a function that calls an external LLM to generate
14	// WASM source code.  The prompt contains the WASM type and inquiry context.
15	// It must return valid TinyGo source code.
16	type ExternalGenerateFn func(ctx context.Context, prompt string) (string, error)
17	
18	// ExternalLLMGenerator uses a provided LLM function or HTTP endpoint to
19	// generate WASM source code.  This is the bootstrap generator — it
20	// produces real TinyGo WASM modules via a trained LLM while the
21	// internal Gorgonite model is still being pre-trained.
22	type ExternalLLMGenerator struct {
23		generateFn ExternalGenerateFn
24		httpURL    string
25		httpClient *http.Client
26	}
27	
28	// NewExternalLLMGenerator creates an external generator that calls the
29	// given function for each generation request.
30	func NewExternalLLMGenerator(fn ExternalGenerateFn) *ExternalLLMGenerator {
31		return &ExternalLLMGenerator{generateFn: fn}
32	}
33	
34	// NewExternalLLMGeneratorWithURL creates an external generator that POSTs
35	// generation requests to the given HTTP endpoint.  The endpoint receives
36	// a JSON body with "wasm_type", "prompt" and returns JSON with "source".
37	func NewExternalLLMGeneratorWithURL(url string) *ExternalLLMGenerator {
38		return &ExternalLLMGenerator{
39			httpURL: url,
40			httpClient: &http.Client{
41				Timeout: 120 * time.Second,
42			},
43		}
44	}
45	
46	// GenerateSource builds a prompt and generates WASM source via the
47	// configured external LLM.
48	func (g *ExternalLLMGenerator) GenerateSource(ctx context.Context, wasmType WASMType, inquiry interface{}) (string, error) {
49		prompt := BuildWASMGenerationPrompt(wasmType, inquiry)
50	
51		if g.generateFn != nil {
52			return g.generateFn(ctx, prompt)
53		}
54	
55		if g.httpURL != "" {
56			return g.generateViaHTTP(ctx, prompt, wasmType)
57		}
58	
59		return "", fmt.Errorf("external generator: no generate function or HTTP URL configured")
60	}
61	
62	// generateViaHTTP sends the prompt to the configured HTTP endpoint.
63	func (g *ExternalLLMGenerator) generateViaHTTP(ctx context.Context, prompt string, wasmType WASMType) (string, error) {
64		body := map[string]string{
65			"wasm_type": string(wasmType),
66			"prompt":    prompt,
67		}
68		jsonBody, err := json.Marshal(body)
69		if err != nil {
70			return "", fmt.Errorf("external generator: marshal request: %w", err)
71		}
72	
73		req, err := http.NewRequestWithContext(ctx, http.MethodPost, g.httpURL, bytes.NewReader(jsonBody))
74		if err != nil {
75			return "", fmt.Errorf("external generator: create request: %w", err)
76		}
77		req.Header.Set("Content-Type", "application/json")
78	
79		resp, err := g.httpClient.Do(req)
80		if err != nil {
81			return "", fmt.Errorf("external generator: HTTP call: %w", err)
82		}
83		defer resp.Body.Close()
84	
85		respBody, err := io.ReadAll(resp.Body)
86		if err != nil {
