143	
144		// Phase 1: Initialize deterministic embedder for cosine similarity searches
145		embedder := embeddings.NewDeterministicService()
146	
147		var hashNet *HashNetworkWrapper
148		if cfg.UseHashNetwork {
149			hashNet = NewHashNetworkWrapper()
150			hashNet.SetAvailable(true)
151		}
152	
153		svc := &HEARTService{
154			gpt:       gpt,
155			bridge:    cfg.getBridge(),
156			tokenizer: tokIface,
157			embedder:  embedder,
158			compiler:  NewWASMCompiler(cfg.TinyGoPath, cfg.WASMOutDir),
159			verifier:  NewBidirectionalVerifier(),
