170		// Set up the generator switcher: internal Gorgonite pipeline + optional
171		// external LLM bootstrap generator.
172		internalGen := NewInternalGPTGenerator(svc)
173		var externalGen WASMSourceGenerator
174		if cfg.ExternalGeneratorURL != "" {
175			externalGen = NewExternalLLMGeneratorWithURL(cfg.ExternalGeneratorURL)
176		} else if cfg.ExternalGenerateFn != nil {
177			externalGen = NewExternalLLMGenerator(cfg.ExternalGenerateFn)
178		}
