180		// Use the GPT itself as the training-state provider: IsReady() returns
181		// true once SetTrained(true) has been called (e.g. after pre-training
182		// completes).  Until then, the external generator is used.
183		var trainingProvider TrainingStateProvider
184		if gpt != nil {
