234	// classifyInquiry maps an HTTP path to a WASMType.
235	func classifyInquiry(path string) WASMType {
236		switch {
237		case contains(path, "advise"):
238			return WASMTypeRule
239		case contains(path, "resolve"):
240			return WASMTypeResolution
241		case contains(path, "patch"):
242			return WASMTypePatch
243		default:
244			return WASMTypeRule
245		}
246	}
247	
248	// runGorgoniteInference runs the Gorgonite GPT forward pass and returns logits.
249	// Instruments per-token entropy and routes spikes to gap queues (Phase 13).
250	func (hs *HEARTService) runGorgoniteInference(tokens []int) ([]float32, error) {
251		if hs.gpt == nil {
252			return nil, fmt.Errorf("gpt not initialized")
253		}
254		logitsNode, err := hs.gpt.Forward(false)
255		if err != nil {
256			return nil, fmt.Errorf("gpt forward: %w", err)
257		}
258		vm := gorgonia.NewTapeMachine(hs.gpt.graph)
259		defer vm.Close()
260		if err := vm.RunAll(); err != nil {
261			return nil, fmt.Errorf("gpt vm: %w", err)
262		}
263		if logitsNode.Value() == nil {
264			return nil, fmt.Errorf("nil logits value")
265		}
266		data, ok := logitsNode.Value().Data().([]float32)
267		if !ok {
268			return nil, fmt.Errorf("unexpected logits type")
269		}
270	
271		// Per-token entropy instrumentation (Phase 13).
272		entropy := computeEntropy(data)
273		threshold := 3.0
274		if hs.config != nil && hs.config.EntropySpikethreshold > 0 {
275			threshold = hs.config.EntropySpikethreshold
276		}
277		if entropy > threshold {
278			hs.handleEntropySpike(entropy, threshold)
279		}
280	
281		return data, nil
282	}
283	
284	// handleEntropySpike routes high-entropy token activations to gap queues (Phase 13).
285	// Routes by WASM type: OntologyGap, NovelError, or SystemAlert.
286	// Emits OntologyDrift event when delta signal indices exceed threshold (Phase 13.3).
287	func (hs *HEARTService) handleEntropySpike(entropy, threshold float64) {
288		log.Printf("HEART entropy spike: %.4f > %.4f, routing to gap queue", entropy, threshold)
289		hs.mu.Lock()
290		if hs.stats.HeuristicUsage == nil {
291			hs.stats.HeuristicUsage = make(map[string]uint64)
292		}
293		hs.stats.HeuristicUsage["entropy_spike"]++
294	
295		// Gap queue routing by WASM type (Phase 13.1)
296		gapQueue := "SystemAlert" // default
297		if hs.stats.HeuristicUsage["rule"] > 0 {
298			gapQueue = "OntologyGap"
299		} else if hs.stats.HeuristicUsage["resolution"] > 0 {
300			gapQueue = "NovelError"
301		}
302		hs.stats.HeuristicUsage[gapQueue]++
303		hs.mu.Unlock()
304	
305		// OntologyDrift detection: compare current vs baseline signal indices (Phase 13.3)
306		// Requires SetBaseline() to be called first with a VarianceAnalyzer snapshot
307		hs.mu.Lock()
308		baseline := hs.baseline
309		hs.mu.Unlock()
310	
311		if baseline != nil {
312			// Would compare current signal indices against baseline
313			// Log that drift detection is active
314			log.Printf("OntologyDrift detection active: baseline with %d signal indices from %v",
315				len(baseline.SignalIndices), baseline.Timestamp)
316		}
317	}
318	
319	// SetBaseline sets the baseline signal indices for OntologyDrift detection.
320	// Call this with signal indices from a reference VarianceAnalyzer.
321	func (hs *HEARTService) SetBaseline(signalIndices []int) {
322		snapshot := &VarianceAnalyzerSnapshot{
323			SignalIndices: signalIndices,
324			Timestamp:     time.Now(),
325		}
326		hs.mu.Lock()
327		hs.baseline = snapshot
328		hs.mu.Unlock()
329		log.Printf("OntologyDrift baseline set with %d signal indices", len(snapshot.SignalIndices))
330	}
331	
332	// CheckOntologyDrift compares current signal indices against baseline.
333	// Returns true if the Jaccard distance exceeds the threshold (0.4).
334	// Uses DeltaSignalIndices logic: computes symmetric difference / union.
335	func (hs *HEARTService) CheckOntologyDrift(currentIndices []int, threshold float32) (bool, []int) {
336		hs.mu.RLock()
337		baseline := hs.baseline
338		hs.mu.RUnlock()
339	
340		if baseline == nil || len(baseline.SignalIndices) == 0 {
341			return false, nil
342		}
343	
344		// Build sets for Jaccard distance
345		bSet := make(map[int]bool)
346		for _, idx := range baseline.SignalIndices {
347			bSet[idx] = true
348		}
349		aSet := make(map[int]bool)
350		for _, idx := range currentIndices {
351			aSet[idx] = true
352		}
353	
354		intersection := 0
355		union := len(bSet)
356		for idx := range aSet {
357			if bSet[idx] {
358				intersection++
359			} else {
360				union++
361			}
362		}
363	
364		if union == 0 {
365			return false, nil
366		}
367	
368		jaccardDist := float32(1) - float32(intersection)/float32(union)
369		if jaccardDist > threshold {
370			// Return symmetric difference as deltas
371			var deltas []int
372			for idx := range bSet {
373				if !aSet[idx] {
374					deltas = append(deltas, idx)
375				}
376			}
377			for idx := range aSet {
378				if !bSet[idx] {
379					deltas = append(deltas, idx)
380				}
381			}
382			log.Printf("OntologyDrift detected: Jaccard distance %.3f > %.1f, %d signal changes",
383				jaccardDist, threshold, len(deltas))
384			return true, deltas
385		}
386	
387		return false, nil
388	}
