390	// computeEntropy computes the Shannon entropy of the softmax distribution over logits.
391	func computeEntropy(logits []float32) float64 {
392		if len(logits) == 0 {
393			return 0
394		}
395		maxLogit := float64(logits[0])
396		for _, v := range logits {
397			if float64(v) > maxLogit {
398				maxLogit = float64(v)
399			}
400		}
401		sum := 0.0
402		probs := make([]float64, len(logits))
403		for i, v := range logits {
404			probs[i] = math.Exp(float64(v) - maxLogit)
405			sum += probs[i]
406		}
407		entropy := 0.0
408		for _, p := range probs {
409			p /= sum
410			if p > 0 {
411				entropy -= p * math.Log(p)
412			}
413		}
414		return entropy
415	}
