417	// process runs the multi-turn HEART cognitive loop with HashNetwork fast-path (Phase 7.2 + 8.2).
418	// When the GeneratorSwitcher selects GeneratorExternal, the external LLM
419	// generates the WASM source directly (bootstrap mode) instead of running
420	// the full Gorgonite pipeline.
421	func (hs *HEARTService) process(ctx context.Context, wasmType WASMType, inquiry interface{}) (WASMDecision, error) {
422		hs.mu.RLock()
423		switcher := hs.generatorSwitcher
424		hs.mu.RUnlock()
425	
426		// Bootstrap mode: use external LLM to generate WASM source directly,
427		// bypassing the multi-turn Gorgonite pipeline.
428		if switcher != nil && switcher.ActiveGenerator() == GeneratorExternal {
429			source, err := switcher.GenerateSource(ctx, wasmType, inquiry)
430			if err != nil {
431				return WASMDecision{}, fmt.Errorf("external generation: %w", err)
432			}
433			s4 := &Stage4Result{Source: source, WASMType: wasmType}
434			s3 := &Stage3Result{Rationale: "Generated via external LLM (bootstrap mode)"}
435			d := hs.buildDecision(ctx, s4, s3)
436			d.TurnCount = 1
437			return d, nil
438		}
439	
440		maxTurns := 3
441		if hs.config != nil && hs.config.MaxTurns > 0 {
442			maxTurns = hs.config.MaxTurns
443		}
444	
445		// HashNetwork fast-path: if available, bypass the full Gorgonite pipeline (Phase 8.2).
446		if hs.hashNet != nil && hs.hashNet.IsAvailable() {
447			threshold := float32(0.85)
448			if hs.config != nil && hs.config.HashNetworkConfidenceThreshold > 0 {
449				threshold = hs.config.HashNetworkConfidenceThreshold
450			}
451			hash := hs.hashNet.ComputeHash(fmt.Sprintf("%v", inquiry))
452			if hash != "" && threshold > 0 {
453				s4, s3, err := hs.runPipeline(ctx, wasmType, inquiry, nil)
454				if err == nil {
455					d := hs.buildDecision(ctx, s4, s3)
456					d.HashNetworkVerified = true
457					d.TurnCount = 1
458					return d, nil
459				}
460			}
461		}
462	
463		var priorFailures []string
464		var last WASMDecision
465	
466		for turn := 1; turn <= maxTurns; turn++ {
467			s4, s3, err := hs.runPipeline(ctx, wasmType, inquiry, priorFailures)
468			if err != nil {
469				return WASMDecision{}, fmt.Errorf("pipeline error (turn %d): %w", turn, err)
470			}
471			d := hs.buildDecision(ctx, s4, s3)
472			d.TurnCount = turn
473			last = d
474	
475			if d.BidirectionalVerified {
476				return d, nil
477			}
478	
479			failMsg := d.BackwardVerifierMsg
480			if failMsg == "" {
481				failMsg = fmt.Sprintf("verification failed on turn %d", turn)
482			}
483			priorFailures = append(priorFailures, failMsg)
484			log.Printf("HEART process turn %d/%d failed: %s, retrying", turn, maxTurns, failMsg)
485		}
486	
487		return last, nil
488	}
