542	// buildDecision compiles WASM, verifies, audits, and returns a WASMDecision.
543	func (hs *HEARTService) buildDecision(ctx context.Context, s4 *Stage4Result, s3 *Stage3Result) WASMDecision {
544		decision := WASMDecision{
545			WASMType:  s4.WASMType,
546			Rationale: s3.Rationale,
547			TurnCount: 1,
548		}
549	
550		if hs.compiler == nil {
551			return decision
552		}
553	
554		result, err := hs.compiler.Compile(ctx, s4.Source, s4.WASMType)
555		if err != nil {
556			log.Printf("WASM compile error: %v", err)
557			return decision
558		}
559		decision.WASMPath = result.WASMPath
560		decision.WASMHash = result.WASMHash
561	
562		passed, confidence, msg := hs.verifier.Verify(s4.Source, string(s4.WASMType))
563		decision.BidirectionalVerified = passed
564		decision.VerifierConfidence = confidence
565		if passed {
566			decision.ForwardVerifierMsg = msg
567			decision.WazeroExecPassed = true
568		} else {
569			decision.BackwardVerifierMsg = msg
570		}
571	
572		if hs.auditor != nil {
573			inquiryHash := inquiryHashStr(s4.Source)
574			_ = hs.auditor.WriteAuditLog(&AuditRecord{
575				InquiryHash: inquiryHash,
576				WASMSha256:  result.WASMHash,
577				WASMType:    s4.WASMType,
578				Timestamp:   time.Now().UTC().Format(time.RFC3339),
579			})
580		}
581	
582		return decision
583	}
