591	// handleAnalyze processes error inquiries from CORTEX
592	// Now uses the new process() architecture instead of the legacy processInquiry() path
593	func (hs *HEARTService) handleAnalyze(w http.ResponseWriter, r *http.Request) {
594		if r.Method != http.MethodPost {
595			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
596			return
597		}
598	
599		// Enable CORS for WASM clients
600		w.Header().Set("Access-Control-Allow-Origin", "*")
601		w.Header().Set("Access-Control-Allow-Methods", "POST, OPTIONS")
602		w.Header().Set("Access-Control-Allow-Headers", "Content-Type")
603		w.Header().Set("Content-Type", "application/json")
604	
605		if r.Method == http.MethodOptions {
606			w.WriteHeader(http.StatusOK)
607			return
608		}
609	
610		startTime := time.Now()
611	
612		// Parse inquiry
613		var inquiry HEARTErrorInquiry
614		if err := json.NewDecoder(r.Body).Decode(&inquiry); err != nil {
615			http.Error(w, fmt.Sprintf("Invalid request: %v", err), http.StatusBadRequest)
616			return
617		}
618	
619		log.Printf("HEART inquiry: %s (type: %s)", inquiry.ErrorID, inquiry.ErrorType)
620	
621		// Update stats
622		hs.mu.Lock()
623		hs.stats.TotalInquiries++
624		hs.stats.ErrorTypeCounts[inquiry.ErrorType]++
625		hs.mu.Unlock()
626	
627		// Convert HEARTErrorInquiry to DVEErrorInquiry and use new process() architecture
628		dveInquiry := DVEErrorInquiry{
629			DVESessionID: inquiry.ErrorID, // Use ErrorID as session ID for compatibility
630			ErrorType:    inquiry.ErrorType,
631			ErrorMessage:  inquiry.ErrorMessage,
632			ErrorContext:  inquiry.ErrorContext,
633			StackTrace:   inquiry.StackTrace,
634			Metadata:     inquiry.Metadata,
635		}
636	
637		// Use the new process() multi-turn loop with WASMTypeResolution
638		decision, err := hs.process(r.Context(), WASMTypeResolution, dveInquiry)
639		if err != nil {
640			hs.mu.Lock()
641			hs.stats.FailedResponses++
642			hs.mu.Unlock()
643	
644			http.Error(w, fmt.Sprintf("Processing failed: %v", err), http.StatusInternalServerError)
645			return
646		}
647	
648		// Update stats
649		elapsed := time.Since(startTime).Milliseconds()
650		hs.mu.Lock()
651		hs.stats.SuccessfulResponses++
652		hs.stats.TotalResponseTimeMs += float64(elapsed)
653		if float64(elapsed) < hs.stats.MinResponseTimeMs {
654			hs.stats.MinResponseTimeMs = float64(elapsed)
655		}
656		if float64(elapsed) > hs.stats.MaxResponseTimeMs {
657			hs.stats.MaxResponseTimeMs = float64(elapsed)
658		}
659		hs.stats.HeuristicUsage[fmt.Sprintf("turn_%d", decision.TurnCount)]++
660		hs.mu.Unlock()
661	
662		// Convert WASMDecision to HEARTHeuristicResponse for backward compatibility
663		response := &HEARTHeuristicResponse{
664			InquiryID:          inquiry.ErrorID,
665			CommandVector:      decisionToCommandVector(decision),
666			AlertLevel:         decisionToAlertLevel(decision.WASMType),
667			HeuristicID:        decisionToHeuristicID(decision),
668			TargetNodeID:       0, // Default for backward compatibility
669			ConfidenceScore:    decision.VerifierConfidence,
670			ActionParameters:   decisionToActionParams(decision),
671			AnalysisSummary:    decision.Rationale,
672			RecommendedActions: hs.generateRecommendedActions(&inquiry, decisionToHeuristicID(decision)),
673			Timestamp:          uint64(time.Now().Unix()),
674		}
675	
676		response.ProcessingTimeMs = float32(elapsed)
677	
678		// Return response
679		w.WriteHeader(http.StatusOK)
680		json.NewEncoder(w).Encode(response)
681	}
