718	// decisionToActionParams extracts action parameters from decision
719	func decisionToActionParams(d WASMDecision) []float32 {
720		params := make([]float32, 4)
721		if d.BidirectionalVerified {
722			params[0] = 1.0
723		}
724		if d.WazeroExecPassed {
725			params[1] = 1.0
726		}
727		if d.HashNetworkVerified {
728			params[2] = 1.0
729		}
730		params[3] = float32(d.TurnCount)
731		return params
732	}
