734	// processInquiry analyzes the error using HEART transformer
735	func (hs *HEARTService) processInquiry(inquiry *HEARTErrorInquiry) (*HEARTHeuristicResponse, error) {
736		// Prepare input for HEART
737		var heartInput *HEARTInput
738	
739		if inquiry.NetworkMetrics != nil {
740			// Use network metrics if provided
741			heartInput = &HEARTInput{
742				Measurements: [][]float32{inquiry.NetworkMetrics.MeasurementVec},
743				NodeIDs:      []uint32{inquiry.NetworkMetrics.NodeID},
744				TimeSlices:   []uint32{inquiry.NetworkMetrics.TimeSlice},
745			}
746		} else {
747			// Synthesize metrics from error context
748			heartInput = hs.synthesizeMetricsFromError(inquiry)
749		}
750	
751		// Run inference on HEART (Cerebras WSE)
752		output, err := hs.bridge.RunInference(heartInput)
753		if err != nil {
754			return nil, fmt.Errorf("HEART inference failed: %w", err)
755		}
756	
757		// Interpret HEART output
758		if len(output.Commands) == 0 || len(output.Commands[0]) < 8 {
759			return nil, fmt.Errorf("invalid HEART output")
760		}
761	
762		command := output.Commands[0]
763	
764		// Extract command components
765		alertLevel := uint32(command[0])
766		heuristicID := uint32(command[1])
767		targetNodeID := uint32(command[2])
768		confidence := command[3]
769		actionParams := command[4:8]
770	
771		// Generate analysis
772		analysis := hs.generateAnalysisSummary(inquiry, alertLevel, heuristicID)
773		actions := hs.generateRecommendedActions(inquiry, heuristicID)
774		insights := hs.generateDebugInsights(inquiry, command)
775	
776		// Identify patterns (simulated - would use KNIRVGRAPH in production)
777		patterns := hs.identifyErrorPatterns(inquiry)
778	
779		// Find similar errors (simulated - would query KNIRVGRAPH)
780		similarErrors := hs.findSimilarErrors(inquiry)
781	
782		response := &HEARTHeuristicResponse{
783			InquiryID:          inquiry.ErrorID,
784			CommandVector:      command,
785			AlertLevel:         alertLevel,
786			HeuristicID:        heuristicID,
787			TargetNodeID:       targetNodeID,
788			ConfidenceScore:    confidence,
789			ActionParameters:   actionParams,
790			AnalysisSummary:    analysis,
791			RecommendedActions: actions,
792			DebugInsights:      insights,
793			IdentifiedPatterns: patterns,
794			SimilarErrors:      similarErrors,
795			Timestamp:          uint64(time.Now().Unix()),
796		}
797	
798		return response, nil
799	}
