873	// generateRecommendedActions creates actionable recommendations.
874	// When a Gorgonite GPT and tokenizer are available it uses inference to select
875	// actions; otherwise it falls back to heuristic rules (Phase 2.4).
876	func (hs *HEARTService) generateRecommendedActions(inquiry *HEARTErrorInquiry, heuristicID uint32) []string {
877		if hs.gpt != nil && hs.tokenizer != nil {
878			prompt := fmt.Sprintf("error_type:%s message:%s", inquiry.ErrorType, inquiry.ErrorMessage)
879			tokens := hs.tokenizer.Encode(prompt)
880			logits, err := hs.runGorgoniteInference(tokens)
881			if err == nil && len(logits) > 0 {
882				return hs.actionsFromLogits(logits)
883			}
884		}
885	
886		// Heuristic fallback.
887		switch heuristicID {
888		case 101:
889			return []string{
890				"Validate input types before processing",
891				"Add type guards to prevent undefined access",
892				"Review variable initialization",
893			}
894		case 201:
895			return []string{
896				"Implement exponential backoff for retries",
897				"Check endpoint availability and CORS configuration",
898				"Add fallback to cached data if available",
899			}
900		case 301:
901			return []string{
902				"Verify model weights are loaded correctly",
903				"Check input tensor shapes and formats",
904				"Consider reloading model weights",
905				"Apply relevant LoRA adapter if available",
906			}
907		default:
908			return []string{
909				"Review error context and stack trace",
910				"Check system logs for related errors",
911				"Consider retry with exponential backoff",
912			}
913		}
914	}
915	
916	// actionPool is the set of possible actions indexed by logit argmax bucket.
917	var actionPool = []string{
918		"Validate input types before processing",
919		"Implement exponential backoff for retries",
920		"Verify model weights are loaded correctly",
921		"Add type guards to prevent undefined access",
922		"Check endpoint availability and CORS configuration",
923		"Review variable initialization",
924		"Check input tensor shapes and formats",
925		"Review error context and stack trace",
926	}
927	
928	// actionsFromLogits selects up to 3 actions using the top-3 logit indices.
929	func (hs *HEARTService) actionsFromLogits(logits []float32) []string {
930		n := len(actionPool)
931		if n == 0 {
932			return nil
933		}
934		// Top-3 argmax without full sort.
935		selected := make([]string, 0, 3)
936		used := make(map[int]bool)
937		for range 3 {
938			best, bestIdx := float32(-1e9), -1
939			for i, v := range logits {
940				bucket := i % n
941				if !used[bucket] && v > best {
942					best, bestIdx = v, bucket
943				}
944			}
945			if bestIdx < 0 {
946				break
947			}
948			selected = append(selected, actionPool[bestIdx])
949			used[bestIdx] = true
950		}
951		return selected
952	}
