968	// identifyErrorPatterns finds known patterns in the error
969	func (hs *HEARTService) identifyErrorPatterns(inquiry *HEARTErrorInquiry) []ErrorPattern {
970		patterns := []ErrorPattern{}
971	
972		// Simple pattern matching (would use KNIRVGRAPH in production)
973		if contains(inquiry.ErrorMessage, "undefined") {
974			patterns = append(patterns, ErrorPattern{
975				PatternID:       "PTN001",
976				PatternName:     "Undefined Reference",
977				Description:     "Accessing undefined variable or property",
978				MatchConfidence: 0.85,
979				Indicators:      []string{"undefined", "null reference"},
980			})
981		}
982	
983		if contains(inquiry.ErrorType, "Network") {
984			patterns = append(patterns, ErrorPattern{
985				PatternID:       "PTN002",
986				PatternName:     "Network Connectivity",
987				Description:     "Network request failed or timed out",
988				MatchConfidence: 0.90,
989				Indicators:      []string{"fetch failed", "timeout", "CORS"},
990			})
991		}
992	
993		return patterns
994	}
995	
996	// findSimilarErrors queries for similar past errors using embedder cosine similarity.
997	// Falls back to heuristic if embedder is unavailable (Phase 1.3).
998	func (hs *HEARTService) findSimilarErrors(inquiry *HEARTErrorInquiry) []SimilarError {
999		// Use embedder-based cosine similarity if available
1000		if hs.embedder != nil {
1001			query := inquiry.ErrorType + " " + inquiry.ErrorMessage + " " + inquiry.ErrorContext
1002			queryEmb := hs.embedder.GetEmbedding(query)
1003	
1004			// Simulated known errors with pre-computed embeddings
1005			knownErrors := []struct {
1006				ID         string
1007				Text        string
1008				Resolution  string
1009				SkillID     string
1010			}{
1011				{"ERR-2024-001", "TypeError undefined validation", "Applied type validation LoRA adapter", "skill-typecheck-v1"},
1012				{"ERR-2024-042", "NetworkError timeout fetch", "Network timeout retry logic", "skill-network-v2"},
1013			}
1014	
1015			results := make([]SimilarError, 0, len(knownErrors))
1016			for _, k := range knownErrors {
1017				knownEmb := hs.embedder.GetEmbedding(k.Text)
1018				score := embeddings.CosineSimilarity(queryEmb, knownEmb)
1019				if score > 0.5 { // threshold for similarity
1020					results = append(results, SimilarError{
1021						ErrorID:         k.ID,
1022						ErrorType:       inquiry.ErrorType,
1023						SimilarityScore: score,
1024						Resolution:      k.Resolution,
1025						SkillID:         k.SkillID,
1026					})
1027				}
1028			}
1029			if len(results) > 0 {
1030				return results
1031			}
1032		}
1033	
1034		// Fallback heuristic
1035		return []SimilarError{
1036			{
1037				ErrorID:         "ERR-2024-001",
1038				ErrorType:       inquiry.ErrorType,
1039				SimilarityScore: 0.78,
1040				Resolution:      "Applied type validation LoRA adapter",
1041				SkillID:         "skill-typecheck-v1",
1042			},
1043		}
1044	}
