1046	// handleGenerate handles /heart/generate requests from the KNIRVSERVER
1047	// InferenceSwitcher. Returns generated text when the internal model is
1048	// trained, or a 503 with readiness status when it isn't.
1049	func (hs *HEARTService) handleGenerate(w http.ResponseWriter, r *http.Request) {
1050		w.Header().Set("Access-Control-Allow-Origin", "*")
1051		w.Header().Set("Content-Type", "application/json")
1052	
1053		if r.Method != http.MethodPost {
1054			http.Error(w, `{"error":"method not allowed","ready":false}`, http.StatusMethodNotAllowed)
1055			return
1056		}
1057	
1058		var req struct {
1059			Prompt string `json:"prompt"`
1060		}
1061		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
1062			http.Error(w, fmt.Sprintf(`{"error":"bad request: %s","ready":false}`, err), http.StatusBadRequest)
1063			return
1064		}
1065	
1066		hs.mu.RLock()
1067		gpt := hs.gpt
1068		tok := hs.tokenizer
1069		hs.mu.RUnlock()
1070	
1071		if gpt == nil {
1072			w.WriteHeader(http.StatusServiceUnavailable)
1073			json.NewEncoder(w).Encode(map[string]interface{}{
1074				"error":    "gpt not initialized",
1075				"ready":    false,
1076				"progress": 0.0,
1077			})
1078			return
1079		}
1080	
1081		if !gpt.IsReady() {
1082			w.WriteHeader(http.StatusServiceUnavailable)
1083			json.NewEncoder(w).Encode(map[string]interface{}{
1084				"error":    "model not trained",
1085				"ready":    false,
1086				"progress": gpt.Progress(),
1087			})
1088			return
1089		}
1090	
1091		if tok == nil {
1092			w.WriteHeader(http.StatusServiceUnavailable)
1093			json.NewEncoder(w).Encode(map[string]interface{}{
1094				"error":    "tokenizer not available",
1095				"ready":    true,
1096				"progress": 1.0,
1097			})
1098			return
1099		}
1100	
1101		// Tokenize, generate, detokenize
1102		startTokens := tok.Encode(req.Prompt)
1103		maxNewTokens := 256
1104		temperature := float32(0.8)
1105		topK := 40
1106	
1107		outTokens := Generate(gpt, startTokens, maxNewTokens, temperature, topK)
1108		text := tok.Decode(outTokens)
1109	
1110		json.NewEncoder(w).Encode(map[string]interface{}{
1111			"text":    text,
1112			"ready":   true,
1113			"tokens":  len(outTokens),
1114		})
1115	}
1116	
1117	// handleHealth returns service health status including model readiness.
1118	func (hs *HEARTService) handleHealth(w http.ResponseWriter, r *http.Request) {
1119		w.Header().Set("Access-Control-Allow-Origin", "*")
1120		w.Header().Set("Content-Type", "application/json")
1121	
1122		var ready bool
1123		var progress float64
1124		if hs.gpt != nil {
1125			ready = hs.gpt.IsReady()
1126			progress = hs.gpt.Progress()
1127		}
1128	
1129		health := map[string]interface{}{
1130			"available":      true,
1131			"status":         "online",
1132			"ready":          ready,
1133			"progress":       progress,
1134			"avg_latency_ms": hs.getAvgLatency(),
1135			"total_queries":  hs.stats.TotalInquiries,
1136			"success_rate":   hs.getSuccessRate(),
1137		}
