1140	}
1141	
1142	// handleStats returns detailed statistics
1143	func (hs *HEARTService) handleStats(w http.ResponseWriter, r *http.Request) {
1144		w.Header().Set("Access-Control-Allow-Origin", "*")
1145		w.Header().Set("Content-Type", "application/json")
1146	
1147		hs.mu.RLock()
1148		defer hs.mu.RUnlock()
1149	
1150		json.NewEncoder(w).Encode(map[string]interface{}{
1151			"total_inquiries":       hs.stats.TotalInquiries,
1152			"successful_responses":  hs.stats.SuccessfulResponses,
1153			"failed_responses":      hs.stats.FailedResponses,
1154			"avg_response_time_ms":  hs.getAvgLatency(),
1155			"min_response_time_ms":  hs.stats.MinResponseTimeMs,
1156			"max_response_time_ms":  hs.stats.MaxResponseTimeMs,
1157			"error_type_counts":     hs.stats.ErrorTypeCounts,
1158			"heuristic_usage":       hs.stats.HeuristicUsage,
1159		})
