1162	func (hs *HEARTService) getAvgLatency() float64 {
1163		hs.mu.RLock()
1164		defer hs.mu.RUnlock()
1165	
1166		if hs.stats.SuccessfulResponses > 0 {
1167			return hs.stats.TotalResponseTimeMs / float64(hs.stats.SuccessfulResponses)
1168		}
