	if err != nil {
		panic(err)
	}

	mask := createCausalMask(g, seqLen)

	for _, block := range blocks {
		x, err = block.Forward(x, mask, false)
		if err != nil {
			panic(err)
		}
	}

	logits, err := gorgonia.Mul(x, outputLayer)
	if err != nil {
		panic(err)
